'use strict';

var Field = require( '@stdlib/plot/vega/field/ctor' );
var isFieldArray = require( './../lib' );

var v = new Field({
	'field': 'amount'
});
var bool = isFieldArray( [ v ] );
console.log( bool );
// => true

bool = isFieldArray( {} );
console.log( bool );
// => false

bool = isFieldArray( 'foo' );
console.log( bool );
// => false
